import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene(); scene.background=new THREE.Color('#111e2c'); scene.fog=new THREE.Fog('#111e2c',25,76);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120); camera.position.set(0,16,24); camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0x9bc7ee,0x263344,2.1)); const sun=new THREE.DirectionalLight(0xffe6c6,3); sun.position.set(-8,18,8); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-24;sun.shadow.camera.right=24;sun.shadow.camera.top=24;sun.shadow.camera.bottom=-24;scene.add(sun);
const blueLight=new THREE.PointLight(0x42baff,24,17);blueLight.position.set(-9,6,-5);scene.add(blueLight);const redLight=new THREE.PointLight(0xef3049,21,15);redLight.position.set(10,4,-6);scene.add(redLight);
const mat=(color,metalness=0,roughness=.65)=>new THREE.MeshStandardMaterial({color,metalness,roughness});
const groundMat=mat('#253342',.2,.82);const ground=new THREE.Mesh(new THREE.PlaneGeometry(90,90),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.09;ground.receiveShadow=true;scene.add(ground);
// Battle-scarred city block, lane markings, debris and the distant skyline.
const grid=new THREE.GridHelper(50,32,0x59748b,0x344657);grid.position.y=-.07;grid.material.transparent=true;grid.material.opacity=.23;scene.add(grid);
for(let i=-5;i<=5;i++){const line=new THREE.Mesh(new THREE.BoxGeometry(.045,.012,18),mat(i===0?'#88969b':'#6d7f88'));line.position.set(i*1.25,-.055,3);scene.add(line)}
const buildings=[];for(let i=0;i<18;i++){const side=i%2?1:-1,z=-12-Math.random()*25,x=side*(13+Math.random()*7),w=3+Math.random()*3,h=7+Math.random()*18,d=3+Math.random()*4;const b=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(i%3?'#293b4a':'#344454',.15,.88));b.position.set(x,h/2-.05,z);b.castShadow=true;b.receiveShadow=true;scene.add(b);const windows=new THREE.Mesh(new THREE.BoxGeometry(w*.83,.06,.02),mat(i%2?'#84c9dd':'#f3c779',.2,.35));windows.position.set(x,h*.57,z+d/2+.015);scene.add(windows);buildings.push(b)}
for(let i=0;i<12;i++){const geo=new THREE.BoxGeometry(.3+Math.random()*.6,.2+Math.random()*.25,.3+Math.random()*.8),m=new THREE.Mesh(geo,mat(i%2?'#59616a':'#853d3c',.4,.7));m.position.set((Math.random()-.5)*18,.14,Math.random()*19-7);m.rotation.y=Math.random()*Math.PI;m.castShadow=true;scene.add(m)}
const heroes={spider:{name:'SPIDER-MAN',letter:'S',primary:'#c51f36',secondary:'#152c59',glow:'#ed3c55',speed:7.3,skill:'WEB BLAST'},iron:{name:'IRON MAN',letter:'I',primary:'#c9402d',secondary:'#d9a746',glow:'#64dfff',speed:6.5,skill:'REPULSOR BLAST'},strange:{name:'DOCTOR STRANGE',letter:'D',primary:'#7d2838',secondary:'#d29a3d',glow:'#b57bff',speed:6.1,skill:'MYSTIC BOLT'}};
const state={running:false,paused:false,over:false,hero:'spider',player:null,hp:100,energy:100,kills:0,combo:0,bestCombo:0,time:0,wave:1,enemies:[],keys:{},cooldowns:{web:0,ultimate:0,dodge:0,attack:0},lastHit:0};
const mats={};function sphere(parent,color,scale,pos,metal=0){const m=new THREE.Mesh(new THREE.SphereGeometry(1,16,12),mat(color,metal,.43));m.scale.set(...scale);m.position.set(...pos);m.castShadow=true;parent.add(m);return m}function limb(parent,color,a,b,r=.13){const v1=new THREE.Vector3(...a),v2=new THREE.Vector3(...b),dir=new THREE.Vector3().subVectors(v2,v1);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r*.78,r,dir.length(),9),mat(color,.12,.48));mesh.position.copy(v1).add(v2).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize());mesh.castShadow=true;parent.add(mesh);return mesh}
function makeHero(type){const def=heroes[type],g=new THREE.Group();const body=sphere(g,def.primary,[.48,.65,.3],[0,1.12,0],.25);sphere(g,def.secondary,[.37,.37,.36],[0,1.96,0],.32);sphere(g,def.primary,[.23,.26,.23],[0,1.98,.12],.2);sphere(g,'#d7e9f2',[.10,.055,.03],[-.13,2.03,.43]);sphere(g,'#d7e9f2',[.10,.055,.03],[.13,2.03,.43]);limb(g,def.secondary,[-.32,1.48,0],[-.55,.83,0],.17);limb(g,def.primary,[-.55,.83,0],[-.48,.35,.08],.12);limb(g,def.secondary,[.32,1.48,0],[.57,.82,0],.17);limb(g,def.primary,[.57,.82,0],[.52,.35,.1],.12);limb(g,def.primary,[-.22,.72,0],[-.27,.3,0],.18);limb(g,def.secondary,[-.27,.3,0],[-.3,.09,.13],.13);limb(g,def.primary,[.22,.72,0],[.27,.3,0],.18);limb(g,def.secondary,[.27,.3,0],[.3,.09,.13],.13);
if(type==='iron'){sphere(g,'#7beeff',[.17,.17,.055],[0,1.23,.30],.45);sphere(g,'#72e8ff',[.09,.04,.03],[-.13,2,.32],.4);sphere(g,'#72e8ff',[.09,.04,.03],[.13,2,.32],.4)}if(type==='strange'){const cape=new THREE.Mesh(new THREE.ConeGeometry(.54,.95,4),mat('#a52732',.15,.56));cape.position.set(0,1.12,-.36);cape.rotation.x=-.14;cape.castShadow=true;g.add(cape);sphere(g,'#e6a438',[0,.99,.31],[0,0,0],.2)}
const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.025,6,40),new THREE.MeshBasicMaterial({color:def.glow,transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;ring.position.y=.04;g.add(ring);const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,24),new THREE.MeshBasicMaterial({color:'#07101b',transparent:true,opacity:.38}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.012;g.add(shadow);g.userData={body,ring,walk:0,type};g.position.set(0,0,5);scene.add(g);return g}
function makeEnemy(boss=false){const g=new THREE.Group(),color=boss?'#642439':'#41334b',armor=boss?'#bd334a':'#747181';sphere(g,color,[boss?.59:.42,boss?.7:.53,.3],[0,boss?1.32:1.04,0],.25);sphere(g,armor,[.34,.34,.33],[0,boss?2.16:1.76,0],.28);sphere(g,'#ff424e',[.09,.055,.04],[-.13,boss?2.2:1.8,.31],.25);sphere(g,'#ff424e',[.09,.055,.04],[.13,boss?2.2:1.8,.31],.25);limb(g,armor,[-.32,1.45,0],[-.55,.8,0],.17);limb(g,color,[-.55,.8,0],[-.48,.34,.05],.12);limb(g,armor,[.32,1.45,0],[.55,.8,0],.17);limb(g,color,[.55,.8,0],[.48,.34,.05],.12);limb(g,color,[-.2,.72,0],[-.25,.25,0],.16);limb(g,armor,[.2,.72,0],[.25,.25,0],.16);const glow=new THREE.PointLight(0xff213d,boss?2:1,3);glow.position.y=1.8;g.add(glow);const ring=new THREE.Mesh(new THREE.TorusGeometry(boss?.77:.57,.022,6,32),new THREE.MeshBasicMaterial({color:boss?'#ff3e59':'#ff6572',transparent:true,opacity:.6}));ring.rotation.x=Math.PI/2;ring.position.y=.03;g.add(ring);g.position.set((Math.random()-.5)*14,0,-8-Math.random()*8);scene.add(g);const hp=boss?12:3;const bar=new THREE.Group();bar.position.y=boss?3.05:2.55;const base=new THREE.Mesh(new THREE.PlaneGeometry(boss?1.7:1.1,.09),mat('#1a1c29'));bar.add(base);const fill=new THREE.Mesh(new THREE.PlaneGeometry(boss?1.65:1.05,.055),new THREE.MeshBasicMaterial({color:boss?'#ffd052':'#fb485c'}));fill.position.z=.01;bar.add(fill);g.add(bar);const e={mesh:g,hp,maxHp:hp,boss,speed:boss?1.45:2.15,attack:0,alive:true,barFill:fill};state.enemies.push(e);return e}
function spawnWave(){state.wave=1;state.enemies.forEach(e=>scene.remove(e.mesh));state.enemies=[];for(let i=0;i<8;i++)makeEnemy(false);$('#enemy-counter').textContent='HOSTILES 0 / 8';$('#wave-number').textContent='01';setTimeout(()=>{if(state.running&&!state.over){makeEnemy(true);$('#boss-alert').classList.add('show');toast('ELITE SIGNATURE DETECTED');setTimeout(()=>$('#boss-alert').classList.remove('show'),3500)}},22000)}
function $(s){return document.querySelector(s)}function clamp(x,a,b){return Math.max(a,Math.min(b,x))}function setHero(type){state.hero=type;const d=heroes[type];$('#hero-name').textContent=d.name;$('#avatar').textContent=d.letter;$('#avatar').style.background=`radial-gradient(circle at 50% 30%,${d.glow},${d.primary})`;$('#objective-text').textContent='DEFEAT THE INVADERS';if(state.player){scene.remove(state.player);state.player=makeHero(type)}}function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1500)}function updateHud(){const pct=Math.ceil(state.hp);$('#hp-fill').style.width=pct+'%';$('#hp-text').textContent=pct+'%';$('#energy-fill').style.width=state.energy+'%';$('#energy-text').textContent=Math.floor(state.energy)+'%';$('#combo-count').textContent=state.combo;$('#combo-box').classList.toggle('active',state.combo>1);$('#enemy-counter').textContent=`HOSTILES ${state.kills} / 8`;$('#timer').textContent=`${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;for(const [id,t] of Object.entries(state.cooldowns)){const b=document.querySelector(`[data-skill="${id}"]`);if(b)b.classList.toggle('cooling',t>0)}}
function startGame(){document.querySelectorAll('.overlay').forEach(x=>x.classList.add('hidden'));state.running=true;state.paused=false;state.over=false;state.hp=100;state.energy=100;state.kills=0;state.combo=0;state.bestCombo=0;state.time=0;state.cooldowns={web:0,ultimate:0,dodge:0,attack:0};if(state.player)scene.remove(state.player);state.player=makeHero(state.hero);spawnWave();toast('MISSION ACTIVE — PROTECT THE CITY');updateHud()}
function nearest(range=9){if(!state.player)return null;let target=null,d=range;for(const e of state.enemies){if(!e.alive)continue;const dist=e.mesh.position.distanceTo(state.player.position);if(dist<d){d=dist;target=e}}return target}
const effects=[];function burst(pos,color='#67dcff',count=10,size=.12){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(size*(.6+Math.random()),7,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));mesh.position.copy(pos);scene.add(mesh);const v=new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5);effects.push({mesh,v,life:.45+Math.random()*.45,max:.9})}}
function hurtEnemy(e,dmg){if(!e||!e.alive)return;e.hp-=dmg; e.barFill.scale.x=Math.max(.001,e.hp/e.maxHp);e.mesh.position.x+=(e.mesh.position.x-state.player.position.x)*.045;e.mesh.position.z+=(e.mesh.position.z-state.player.position.z)*.045;burst(e.mesh.position.clone().add(new THREE.Vector3(0,1.25,0)),heroes[state.hero].glow,6,.07);state.combo++;state.bestCombo=Math.max(state.bestCombo,state.combo);state.lastHit=state.time;state.energy=clamp(state.energy+2,0,100);if(e.hp<=0){e.alive=false;scene.remove(e.mesh);state.kills++;state.energy=clamp(state.energy+8,0,100);state.hp=clamp(state.hp+3,0,100);burst(e.mesh.position.clone().add(new THREE.Vector3(0,1,0)),e.boss?'#ffad53':'#ff4a62',22,.12);if(e.boss){toast('ELITE ELIMINATED');finish(true)}else if(state.kills>=8&&!state.enemies.some(x=>x.boss&&x.alive)){finish(true)}}}
function attack(){if(!state.running||state.paused||state.over||state.cooldowns.attack>0)return;state.cooldowns.attack=.31;const target=nearest(4.5);if(target){hurtEnemy(target,heroes[state.hero].name==='SPIDER-MAN'?1.5:2);const dir=target.mesh.position.clone().sub(state.player.position);state.player.rotation.y=Math.atan2(dir.x,dir.z);state.player.userData.body.scale.x=1.18;setTimeout(()=>{if(state.player)state.player.userData.body.scale.x=1},100)}else{burst(state.player.position.clone().add(new THREE.Vector3(0,1,0)),heroes[state.hero].glow,4,.055)}}
function ability(kind){if(!state.running||state.paused||state.over)return;const cost=kind==='ultimate'?50:20;if(state.energy<cost){toast('NOT ENOUGH ENERGY');return}if(state.cooldowns[kind]>0)return;state.energy-=cost;state.cooldowns[kind]=kind==='ultimate'?9:4.2;if(kind==='web'){const e=nearest(13);if(e){hurtEnemy(e,e.boss?3:4);toast(heroes[state.hero].skill+'!')}else toast('NO TARGET IN RANGE');burst(state.player.position.clone().add(new THREE.Vector3(0,1.4,0)),heroes[state.hero].glow,16,.09)}else{for(const e of state.enemies){if(e.alive&&e.mesh.position.distanceTo(state.player.position)<13)hurtEnemy(e,e.boss?6:5)}burst(state.player.position.clone().add(new THREE.Vector3(0,1,0)),'#ffd15e',40,.15);toast('ULTIMATE — UNLEASHED!')}}
function dodge(){if(!state.running||state.paused||state.cooldowns.dodge>0)return;state.cooldowns.dodge=1.3;state.player.userData.dodge=.24;const k=state.keys;let dx=(k.KeyD?1:0)-(k.KeyA?1:0),dz=(k.KeyS?1:0)-(k.KeyW?1:0);if(!dx&&!dz)dz=1;const l=Math.hypot(dx,dz)||1;state.player.position.x+=dx/l*2.7;state.player.position.z+=dz/l*2.7;state.player.position.x=clamp(state.player.position.x,-11,11);state.player.position.z=clamp(state.player.position.z,-12,12);burst(state.player.position.clone().add(new THREE.Vector3(0,.8,0)),heroes[state.hero].glow,8,.07)}
function finish(win){if(state.over)return;state.over=true;state.running=false;$('#end-kicker').innerHTML=`<span></span> ${win?'MISSION COMPLETE':'MISSION FAILED'}`;$('#end-title').textContent=win?'CITY SAVED.':'HERO DOWN.';$('#end-copy').textContent=win?'The invading forces have been driven back. New York is safe — for now.':'The city needs you. Get back out there and turn the tide.';$('#result-kills').textContent=state.kills;$('#result-time').textContent=$('#timer').textContent;$('#result-combo').textContent=state.bestCombo;$('#end-screen').classList.remove('hidden')}
// Controls: keyboard and touch share the same action path.
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();state.keys[e.code]=true;if(e.repeat)return;if(e.code==='Space')attack();if(e.code==='KeyQ')ability('web');if(e.code==='KeyE')ability('ultimate');if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();if(e.code==='Escape')togglePause()});window.addEventListener('keyup',e=>state.keys[e.code]=false);
$('#start-btn').onclick=startGame;$('#restart-btn').onclick=startGame;$('#resume-btn').onclick=togglePause;$('#pause-btn').onclick=togglePause;$('#switch-btn').onclick=()=>{const types=Object.keys(heroes),next=types[(types.indexOf(state.hero)+1)%types.length];setHero(next);toast('HERO SWITCHED — '+heroes[next].name)};$('#attack-btn').onclick=attack;$('#dodge-btn').onclick=dodge;document.querySelector('[data-skill="web"]').onclick=()=>ability('web');document.querySelector('[data-skill="ultimate"]').onclick=()=>ability('ultimate');document.querySelectorAll('.hero-pick').forEach(b=>b.onclick=()=>{document.querySelectorAll('.hero-pick').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');setHero(b.dataset.hero)});function togglePause(){if(!state.running&&!state.paused)return;state.paused=!state.paused;$('#pause-screen').classList.toggle('hidden',!state.paused)}
const touchKeys={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD'};document.querySelectorAll('[data-dir]').forEach(b=>{const code=touchKeys[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();state.keys[code]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>state.keys[code]=false))});document.querySelectorAll('[data-action]').forEach(b=>{const act=b.dataset.action,fn=act==='attack'?attack:act==='dodge'?dodge:()=>ability(act);b.addEventListener('pointerdown',e=>{e.preventDefault();fn()})});$('#dismiss-tip').onclick=()=>$('.mobile-tip').style.display='none';let sound=false;$('#sound-btn').onclick=()=>{sound=!sound;$('#sound-btn').style.color=sound?'#55dcff':'';toast(sound?'SOUND ON':'SOUND OFF')};
const clock=new THREE.Clock();function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.04);if(state.running&&!state.paused){state.time+=dt;state.energy=clamp(state.energy+dt*1.2,0,100);for(const k in state.cooldowns)state.cooldowns[k]=Math.max(0,state.cooldowns[k]-dt);if(state.time-state.lastHit>2.8)state.combo=0;const p=state.player,k=state.keys;let dx=(k.KeyD||k.ArrowRight?1:0)-(k.KeyA||k.ArrowLeft?1:0),dz=(k.KeyS||k.ArrowDown?1:0)-(k.KeyW||k.ArrowUp?1:0),len=Math.hypot(dx,dz);if(len){dx/=len;dz/=len;p.position.x+=dx*heroes[state.hero].speed*dt;p.position.z+=dz*heroes[state.hero].speed*dt;p.rotation.y=Math.atan2(dx,dz);p.userData.walk+=dt*12;p.position.y=Math.abs(Math.sin(p.userData.walk))*.07}else p.position.y=0;p.position.x=clamp(p.position.x,-11,11);p.position.z=clamp(p.position.z,-12,12);p.userData.ring.rotation.z+=dt*1.3;
for(const e of state.enemies){if(!e.alive)continue;e.attack-=dt;const v=p.position.clone().sub(e.mesh.position),dist=v.length();if(dist>1.8){e.mesh.position.add(v.normalize().multiplyScalar(e.speed*dt));e.mesh.rotation.y=Math.atan2(v.x,v.z)}else if(e.attack<=0){e.attack=e.boss?1.25:1.7;if(p.userData.dodge>0)continue;state.hp-=e.boss?9:7;state.combo=0;burst(p.position.clone().add(new THREE.Vector3(0,1,0)),'#ff5260',8,.09);if(state.hp<=0){state.hp=0;finish(false)}}e.mesh.position.x=clamp(e.mesh.position.x,-13,13);e.mesh.position.z=clamp(e.mesh.position.z,-13,13)}if(p.userData.dodge>0){p.userData.dodge-=dt;p.children[0].material.transparent=true;p.children[0].material.opacity=.45}else if(p.children[0].material.transparent){p.children[0].material.transparent=false;p.children[0].material.opacity=1}for(let i=effects.length-1;i>=0;i--){const f=effects[i];f.life-=dt;f.mesh.position.addScaledVector(f.v,dt);f.v.y-=5*dt;f.mesh.material.opacity=Math.max(0,f.life/f.max);f.mesh.scale.multiplyScalar(.985);if(f.life<=0){scene.remove(f.mesh);effects.splice(i,1)}}updateHud()}
const target=state.player?state.player.position:new THREE.Vector3(0,0,0);camera.position.x+=(target.x*.25-camera.position.x)*.04;camera.position.z+=(target.z*.22+24-camera.position.z)*.04;camera.lookAt(target.x*.2,0,target.z*.2);renderer.render(scene,camera)}tick();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65))});

