 const effects=[];function burst(pos,color='#67dcff',count=10,size=.12){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(size*(.6+Math.random()),7,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));mesh.position.copy(pos);scene.add(mesh);const v=new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5);effects.push({mesh,v,life:.45+Math.random()*.45,max:.9})}}
 function hurtEnemy(e,dmg){if(!e||!e.alive)return;e.hp-=dmg; e.barFill.scale.x=Math.max(.001,e.hp/e.maxHp);e.mesh.position.x+=(e.mesh.position.x-state.player.position.x)*.045;e.mesh.position.z+=(e.mesh.position.z-state.player.position.z)*.045;burst(e.mesh.position.clone().add(new THREE.Vector3(0,1.25,0)),heroes[state.hero].glow,6,.07);state.combo++;state.bestCombo=Math.max(state.bestCombo,state.combo);state.lastHit=state.time;state.energy=clamp(state.energy+2,0,100);if(e.hp<=0){e.alive=false;scene.remove(e.mesh);state.kills++;state.energy=clamp(state.energy+8,0,100);state.hp=clamp(state.hp+3,0,100);burst(e.mesh.position.clone().add(new THREE.Vector3(0,1,0)),e.boss?'#ffad53':'#ff4a62',22,.12);if(e.boss){toast('ELITE ELIMINATED');finish(true)}else if(state.kills>=8&&!state.bossSpawned){state.bossSpawned=true;makeEnemy(true);$('#objective-text').textContent='ELIMINATE THE ELITE';$('#boss-alert').classList.add('show');toast('ELITE SIGNATURE DETECTED');setTimeout(()=>$('#boss-alert').classList.remove('show'),3500)}}}
 function attack(){if(!state.running||state.paused||state.over||state.cooldowns.attack>0)return;state.cooldowns.attack=.31;const target=nearest(4.5);if(target){hurtEnemy(target,heroes[state.hero].name==='SPIDER-MAN'?1.5:2);const dir=target.mesh.position.clone().sub(state.player.position);state.player.rotation.y=Math.atan2(dir.x,dir.z);state.player.userData.body.scale.x=1.18;setTimeout(()=>{if(state.player)state.player.userData.body.scale.x=1},100)}else{burst(state.player.position.clone().add(new THREE.Vector3(0,1,0)),heroes[state.hero].glow,4,.055)}}
